import { expect, it } from 'vitest';
import { createHash } from 'node:crypto';
import { radar6, horde6 } from '../../src/engine/gen6/tinyTimeline';
import { dexNav6 } from '../../src/engine/gen6/dexNav6';
import type { TinyState } from '../../src/engine/rng/types';

// Digests generated by reference/encounter-vectors.ps1 from v1.0.6 and DexNav.cs.
it('replays 4096 reference configurations for each specialized encounter', () => {
  const hashes = Array.from({length:3}, () => createHash('sha256'));
  const levels = [0,4,5,9,10,24,25,49,50,99,100,101,199,200,201,999];
  const chains = [0,4,5,39,40,49,99];
  for (let i=0;i<4096;i++) {
    const state:TinyState = [i+1,0x99aabbcc,0x55667788,0x11223344];
    const party = i%6+1, chain = chains[i%chains.length]!, boost = !!(i&1);
    const radar = radar6(state,party,chain,boost);
    const horde = horde6(state,party,boost);
    const nav = dexNav6(state,{active:boost,terrain:i%3,specialSlots:!!(i&2),charm:!!(i&4),
      compoundEyes:!!(i&8),searchLevel:levels[(i>>>1)%levels.length]!,chain});
    const lines = [
      [radar.music,...radar.patches.map(p=>[p.ring,p.x,p.y,p.kind].join(','))].join(' '),
      [horde.lead,horde.slot,horde.ha,horde.flutes,horde.items].join(' '),
      nav ? [nav.x,nav.y,nav.terrain,nav.slot,+nav.boost,nav.lead,nav.levelBoost,nav.flute,+nav.ha,
        nav.potential,+nav.eggMove,nav.item,+nav.forcedShiny].join(' ') : '-',
    ];
    lines.forEach((line,j)=>hashes[j]!.update(line+'\r\n'));
  }
  expect(hashes.map(h=>h.digest('hex'))).toEqual([
    '1bc3ec9e8d7801abf6041ccdf9a22f3adcf789c0a594346558655b4717c5ae3a',
    '047cd05c6157974ee7dd5d6815762db25ffd9ce3dd5701e056cdadf0e4a7442e',
    'acc71362887d11d9df6a83996f7be493623b7bb68abc747c47370396e8b582d2',
  ]);
});
